INSERT INTO records (id, version_id, module, record_key, data_json, row_order, change_type, confidence_level, validation_status, primary_source_url, independent_source_url, source_date, verification_date) VALUES (47, 1, 'pipeline_dashboard', 'Korecyte Bio|KOR101', '{"Asset Name":"KOR101","Company":"Korecyte Bio","Target Antigen":"Undisclosed (broadly-targeting CAR + hypoxia switch, pan-solid-tumor)","Delivery Technology":"Lentiviral (in vivo transduction)","Vector / Payload":"DNA (stable integration)","Primary Indication":"Solid tumors (pan-cancer)","Disease Category":"Oncology","Development Stage":"Preclinical","Trial Status / Notes":"HypoxiCAR platform: hypoxia-sensing genetic switch keeps CAR-T cells dormant until they enter a low-oxygen solid tumour microenvironment; King''s College London spin-out with CGT Catapult seed investment via the Innovate UK Cross-Catapult Investment Pilot (May 2026); only solid-tumour-focused in vivo CAR-T in this tracker","CAR Generation":"Undisclosed","Company Announcement URL":"https://korecyte.com/technology/","Credible Press Release URL":"https://www.bioprocessintl.com/deal-making/cgt-catapult-teams-with-korecyte-bio-on-low-oxygen-car-t-platform"}', 26, 'new', 'High', 'Verified', 'https://korecyte.com/technology/', 'https://www.bioprocessintl.com/deal-making/cgt-catapult-teams-with-korecyte-bio-on-low-oxygen-car-t-platform', NULL, '2026-09-04');
INSERT INTO records (id, version_id, module, record_key, data_json, row_order, change_type, confidence_level, validation_status, primary_source_url, independent_source_url, source_date, verification_date) VALUES (48, 1, 'clinical_intelligence', 'Kelonia Therapeutics|KLN-1010', '{"Asset":"KLN-1010","Company":"Kelonia Therapeutics","Indication":"r/r multiple myeloma","n (reported)":18,"ORR / Response":"100% ORR; MRD-neg at 1 mo in all evaluable pts; 4 sCR + 2 VGPR among 6 pts with ≥4 mo follow-up; first pt MRD-neg >10 mo","CRS":"16/18 pts CRS, all Grade 1-2","ICANS":"1 Grade 1 + 1 Grade 3 (Gr3 limited to 3 days)","Deaths":"0","Notable Efficacy/Safety Note":"No lymphodepletion required; FDA Fast Track granted May 2026; dose-dependent in vivo CAR-T expansion and persistence; consistent with outpatient dosing","Company Announcement URL":"https://investor.lilly.com/news-releases/news-release-details/lilly-acquire-kelonia-therapeutics-advance-vivo-car-t-cell","Credible Press Release URL":"https://www.prnewswire.com/news-releases/lilly-to-acquire-kelonia-therapeutics-to-advance-in-vivo-car-t-cell-therapies-302747122.html"}', 0, 'new', 'High', 'Verified', 'https://investor.lilly.com/news-releases/news-release-details/lilly-acquire-kelonia-therapeutics-advance-vivo-car-t-cell', 'https://www.prnewswire.com/news-releases/lilly-to-acquire-kelonia-therapeutics-to-advance-in-vivo-car-t-cell-therapies-302747122.html', NULL, '2026-09-04');
INSERT INTO records (id, version_id, module, record_key, data_json, row_order, change_type, confidence_level, validation_status, primary_source_url, independent_source_url, source_date, verification_date) VALUES (49, 1, 'clinical_intelligence', 'EsoBiotec|ESO-T01', '{"Asset":"ESO-T01","Company":"EsoBiotec","Indication":"Multiple myeloma","n (reported)":"5 (published cohort, Nature Medicine)","ORR / Response":"4/5 objective response; 3 stringent CR; MRD-neg (10^-5) in all 4 evaluable responders by day 60","CRS":"CRS in 4/5 pts (3 Grade 3, 1 Grade 2); biphasic pattern — innate-immune surge <24h pre-dating detectable CAR-T, then a second CAR-T-driven wave; all 5 pts experienced Grade ≥3 adverse events, though no dose-limiting toxicities were reported","ICANS":"1 case (Grade 1)","Deaths":"1 — attributed by investigators to disease progression (extramedullary lesion causing spinal cord compression), not treatment","Notable Efficacy/Safety Note":"Peer-reviewed Phase 1 (n=5) published in Nature Medicine, Mar 2026; no dose-limiting toxicities; highest-severity safety signal reported among in vivo CAR-T assets to date, though death not attributed to therapy","Company Announcement URL":"https://www.astrazeneca.com/media-centre/press-releases/2025/acquisition-of-esobiotec-completed.html","Credible Press Release URL":"https://www.biopharminternational.com/view/astrazeneca-acquire-esobiotec-boosting-cell-therapy-portfolio"}', 1, 'new', 'High', 'Verified', 'https://www.astrazeneca.com/media-centre/press-releases/2025/acquisition-of-esobiotec-completed.html', 'https://www.biopharminternational.com/view/astrazeneca-acquire-esobiotec-boosting-cell-therapy-portfolio', NULL, '2026-09-04');
INSERT INTO records (id, version_id, module, record_key, data_json, row_order, change_type, confidence_level, validation_status, primary_source_url, independent_source_url, source_date, verification_date) VALUES (50, 1, 'clinical_intelligence', 'Interius BioTherapeutics|INT2104', '{"Asset":"INT2104","Company":"Interius BioTherapeutics","Indication":"B-cell malignancies","n (reported)":"Undisclosed","ORR / Response":"Undisclosed","CRS":"Undisclosed","ICANS":"Undisclosed","Deaths":"Undisclosed","Notable Efficacy/Safety Note":"First-in-human dosing in Australia (Oct 2024, INVISE trial); Phase 1 expanded into Europe (Germany/PEI) Jan 2025; data maturing","Company Announcement URL":"https://www.gilead.com/news/news-details/2025/kite-to-acquire-interius-biotherapeutics-to-advance-in-vivo-platform","Credible Press Release URL":"https://www.prnewswire.com/news-releases/interius-biotherapeutics-receives-hrec-approval-and-ctn-clearance-from-the-tga-to-commence-a-phase-1-clinical-trial-for-its-first-in-class-in-vivo-car-therapeutic-for-b-cell-malignancies-302191433.html"}', 2, 'new', 'High', 'Verified', 'https://www.gilead.com/news/news-details/2025/kite-to-acquire-interius-biotherapeutics-to-advance-in-vivo-platform', 'https://www.prnewswire.com/news-releases/interius-biotherapeutics-receives-hrec-approval-and-ctn-clearance-from-the-tga-to-commence-a-phase-1-clinical-trial-for-its-first-in-class-in-vivo-car-therapeutic-for-b-cell-malignancies-302191433.html', NULL, '2026-09-04');
INSERT INTO records (id, version_id, module, record_key, data_json, row_order, change_type, confidence_level, validation_status, primary_source_url, independent_source_url, source_date, verification_date) VALUES (51, 1, 'clinical_intelligence', 'MagicRNA|HN2301', '{"Asset":"HN2301","Company":"MagicRNA","Indication":"Systemic lupus erythematosus (SLE) - 4 of 5 patients also had lupus nephritis","n (reported)":5,"ORR / Response":"Up to 60% CD8+ CAR+ T-cell reprogramming at LOW dose; complete depletion of circulating B cells; SLEDAI score reduction up to 20 points within 3 months","CRS":"None significant reported","ICANS":"None significant reported","Deaths":"0","Notable Efficacy/Safety Note":"Published in NEJM (Sep 2025) - first-ever peer-reviewed clinical data for an mRNA-LNP in vivo CAR-T; no neurotoxicity, no SAEs, no clinically significant liver enzyme elevation in any of 5 patients. Follow-on data showing TISSUE-level B-cell depletion presented as an ASGCT 2026 oral (13 May 2026) and at EULAR 2026 (June 2026).","Company Announcement URL":"https://www.magicrna.com/company/114.html","Credible Press Release URL":"https://www.biospace.com/press-releases/magicrnas-first-in-human-clinical-data-demonstrating-feasibility-of-in-vivo-car-t-therapy-in-systemic-lupus-erythematosus-published-in-the-new-england-journal-of-medicine"}', 3, 'new', 'High', 'Verified', 'https://www.magicrna.com/company/114.html', 'https://www.biospace.com/press-releases/magicrnas-first-in-human-clinical-data-demonstrating-feasibility-of-in-vivo-car-t-therapy-in-systemic-lupus-erythematosus-published-in-the-new-england-journal-of-medicine', NULL, '2026-09-04');
