INSERT INTO records (id, version_id, module, record_key, data_json, row_order, change_type, confidence_level, validation_status, primary_source_url, independent_source_url, source_date, verification_date) VALUES (53, 1, 'clinical_intelligence', 'Legend Biotech|LB2501', '{"Asset":"LB2501","Company":"Legend Biotech","Indication":"R/R B-cell non-Hodgkin lymphoma (B-NHL)","n (reported)":12,"ORR / Response":"100% ORR (6/6) at DL2; CR 83.3% (5/6); all responses ongoing at cutoff","CRS":"66.7% patients, all ≤ Grade 2","ICANS":"None reported","Deaths":0,"Notable Efficacy/Safety Note":"First-in-class CD19/CD20 dual-targeting in vivo CAR-T; no DLTs, SAEs, or ICANS; no lymphodepletion required; dose-dependent CAR-T expansion. Preliminary Phase 1 / early clinical proof-of-concept only (n=12, Apr 1 2026 data cutoff) — directional, not powered for conclusions.","Company Announcement URL":"https://investors.legendbiotech.com/news-releases/news-release-details/legend-biotech-announces-late-breaking-oral-presentation-eha","Credible Press Release URL":"https://www.globenewswire.com/news-release/2026/06/02/3305321/0/en/legend-biotech-announces-late-breaking-oral-presentation-at-eha-2026-showcasing-initial-phase-1-in-vivo-car-t-data-with-lb2501-in-non-hodgkin-lymphoma-nhl.html"}', 5, 'new', 'High', 'Verified', 'https://investors.legendbiotech.com/news-releases/news-release-details/legend-biotech-announces-late-breaking-oral-presentation-eha', 'https://www.globenewswire.com/news-release/2026/06/02/3305321/0/en/legend-biotech-announces-late-breaking-oral-presentation-at-eha-2026-showcasing-initial-phase-1-in-vivo-car-t-data-with-lb2501-in-non-hodgkin-lymphoma-nhl.html', NULL, '2026-09-04');
INSERT INTO records (id, version_id, module, record_key, data_json, row_order, change_type, confidence_level, validation_status, primary_source_url, independent_source_url, source_date, verification_date) VALUES (54, 1, 'clinical_intelligence', 'Genocury Biotech|JY231 (Genocury)', '{"Asset":"JY231 (Genocury)","Company":"Genocury Biotech","Indication":"R/R diffuse large B-cell lymphoma (DLBCL)","n (reported)":1,"ORR / Response":"Complete remission (CR) at 28 days; durable response sustained through 90-day follow-up","CRS":"None reported","ICANS":"None reported","Deaths":0,"Notable Efficacy/Safety Note":"Early human in vivo CAR-T efficacy signal — single R/R DLBCL case (investigator-initiated; company release Apr 2025): CR at 28 days, sustained through 90-day follow-up; no lymphodepletion required","Company Announcement URL":"https://www.prnewswire.com/news-releases/genocury-biotech-annouces-groundbreaking-advance-in-relapsedrefractory-dlbcl-through-pioneering-in-vivo-cd19-car-t-therapy-302442371.html","Credible Press Release URL":"https://www.curetoday.com/view/in-vivo-cd19-car-t-leads-to-remission-in-dlbcl-without-lymphodepletion"}', 6, 'new', 'High', 'Verified', 'https://www.prnewswire.com/news-releases/genocury-biotech-annouces-groundbreaking-advance-in-relapsedrefractory-dlbcl-through-pioneering-in-vivo-cd19-car-t-therapy-302442371.html', 'https://www.curetoday.com/view/in-vivo-cd19-car-t-leads-to-remission-in-dlbcl-without-lymphodepletion', NULL, '2026-09-04');
INSERT INTO records (id, version_id, module, record_key, data_json, row_order, change_type, confidence_level, validation_status, primary_source_url, independent_source_url, source_date, verification_date) VALUES (55, 1, 'clinical_intelligence', 'Immorna|JCXH-213', '{"Asset":"JCXH-213","Company":"Immorna","Indication":"Systemic sclerosis","n (reported)":1,"ORR / Response":"Peripheral B-cells undetectable through 2-week observation window; first tissue (lymph node biopsy)-level B-cell depletion shown for an in vivo CAR-T; autoantibody titers declined","CRS":"None reported","ICANS":"None reported","Deaths":0,"Notable Efficacy/Safety Note":"First-in-human dosing announced Mar 2025; Apr 2026 update reported deep tissue (lymph-node) B-cell depletion in a systemic sclerosis patient — a first for in vivo CAR-T; no CRS or liver-enzyme abnormalities observed","Company Announcement URL":"https://www.immornabio.com/","Credible Press Release URL":"https://endpoints.news/in-vivo-car-t-race-for-autoimmune-grows-as-two-rna-startups-enter-the-clinic/"}', 7, 'new', 'High', 'Verified', 'https://www.immornabio.com/', 'https://endpoints.news/in-vivo-car-t-race-for-autoimmune-grows-as-two-rna-startups-enter-the-clinic/', NULL, '2026-09-04');
INSERT INTO records (id, version_id, module, record_key, data_json, row_order, change_type, confidence_level, validation_status, primary_source_url, independent_source_url, source_date, verification_date) VALUES (56, 1, 'clinical_intelligence', 'Vivacta Bio|GT801', '{"Asset":"GT801","Company":"Vivacta Bio","Indication":"R/R CD19+ B-cell malignancies (NHL)","n (reported)":"Undisclosed (early IIT cohort)","ORR / Response":"Encouraging early clinical activity reported (efficient CAR expression, deep B-cell depletion); specific ORR/CR figures not disclosed in the English-language release","CRS":"Preclinical data reported minimal cytokine release (IL-6, TNF-α); clinical CRS data for the human cohort not yet disclosed","ICANS":"Undisclosed","Deaths":"Undisclosed","Notable Efficacy/Safety Note":"T-LNP (CLAMP)-delivered mRNA CD19 CAR-T; >30-fold in vivo CAR-T expansion reported preclinically; first-in-human data presented at ASH 2025 (oral session)","Company Announcement URL":"https://www.prnewswire.com/news-releases/vivacta-bio-closed-series-a-and-series-a-financing-of-over-us50-million-302756983.html","Credible Press Release URL":"https://www.prnewswire.com/news-releases/vivacta-bio-announces-promising-first-in-human-results-for-gt801-an-in-vivo-car-t-therapy-in-non-hodgkins-lymphoma-at-the-2025-ash-annual-meeting-302633966.html"}', 8, 'new', 'High', 'Verified', 'https://www.prnewswire.com/news-releases/vivacta-bio-closed-series-a-and-series-a-financing-of-over-us50-million-302756983.html', 'https://www.prnewswire.com/news-releases/vivacta-bio-announces-promising-first-in-human-results-for-gt801-an-in-vivo-car-t-therapy-in-non-hodgkins-lymphoma-at-the-2025-ash-annual-meeting-302633966.html', NULL, '2026-09-04');
INSERT INTO records (id, version_id, module, record_key, data_json, row_order, change_type, confidence_level, validation_status, primary_source_url, independent_source_url, source_date, verification_date) VALUES (57, 1, 'technology_intelligence', 'LNP + mRNA (transient)', '{"Delivery Class":"LNP + mRNA (transient)","Companies":"Capstan Therapeutics, CREATE Medicines, Vivacta Bio","Payload Persistence":"Days to weeks (non-integrating)","Mechanism Summary":"Antibody/ligand-decorated lipid nanoparticle delivers CAR-encoding mRNA to circulating T cells","Key Advantage(s) Claimed":"Potentially cleaner safety profile; repeat/titratable dosing possible","Key Risk(s) Considered":"Shorter persistence may limit durability vs. autologous CAR-T","Representative Asset":"CPTX2309, CRT-402, GT801","Company Announcement URL":"https://news.abbvie.com/2025-06-30-AbbVie-to-Acquire-Capstan-Therapeutics,-Further-Strengthening-Commitment-to-Transforming-Patient-Care-in-Immunology","Credible Press Release URL":"https://www.prnewswire.com/news-releases/abbvie-completes-acquisition-of-capstan-therapeutics-302533462.html"}', 0, 'new', 'High', 'Verified', 'https://news.abbvie.com/2025-06-30-AbbVie-to-Acquire-Capstan-Therapeutics,-Further-Strengthening-Commitment-to-Transforming-Patient-Care-in-Immunology', 'https://www.prnewswire.com/news-releases/abbvie-completes-acquisition-of-capstan-therapeutics-302533462.html', NULL, '2026-09-04');
INSERT INTO records (id, version_id, module, record_key, data_json, row_order, change_type, confidence_level, validation_status, primary_source_url, independent_source_url, source_date, verification_date) VALUES (58, 1, 'technology_intelligence', 'LNP + Circular RNA', '{"Delivery Class":"LNP + Circular RNA","Companies":"Orna Therapeutics, Orbital Therapeutics","Payload Persistence":"Extended vs. linear mRNA, still non-integrating","Mechanism Summary":"Circular RNA scaffold extends half-life of CAR expression relative to standard mRNA","Key Advantage(s) Claimed":"Longer transient expression window than linear mRNA","Key Risk(s) Considered":"Still non-integrating; durability data limited","Representative Asset":"ORN-252, OTX-201","Company Announcement URL":"https://investor.lilly.com/news-releases/news-release-details/lilly-acquire-orna-therapeutics-advance-cell-therapies","Credible Press Release URL":"https://www.biopharmadive.com/news/bristol-myers-acquire-orbital-in-vivo-cell-therapy/802573/"}', 1, 'new', 'High', 'Verified', 'https://investor.lilly.com/news-releases/news-release-details/lilly-acquire-orna-therapeutics-advance-cell-therapies', 'https://www.biopharmadive.com/news/bristol-myers-acquire-orbital-in-vivo-cell-therapy/802573/', NULL, '2026-09-04');
INSERT INTO records (id, version_id, module, record_key, data_json, row_order, change_type, confidence_level, validation_status, primary_source_url, independent_source_url, source_date, verification_date) VALUES (59, 1, 'technology_intelligence', 'Lentiviral (stable integration)', '{"Delivery Class":"Lentiviral (stable integration)","Companies":"Umoja Biopharma, Interius BioTherapeutics, EsoBiotec, Kelonia Therapeutics, Pregene Biopharma, Legend Biotech, Vyriad, Korecyte Bio","Payload Persistence":"Long-term (genomic integration)","Mechanism Summary":"Engineered, replication-incompetent lentiviral particles with T-cell-targeting envelope proteins (e.g., anti-CD3, anti-CD7, anti-CD8 scFv) deliver CAR-encoding DNA","Key Advantage(s) Claimed":"Persistence intended to mirror autologous CAR-T; single administration","Key Risk(s) Considered":"Insertional mutagenesis / secondary malignancy risk considered a class issue; historically harder to manufacture at scale","Representative Asset":"UB-VV111, INT2104, ESO-T01, KLN-1010, LB2501, VV169, KOR101","Company Announcement URL":"https://investor.lilly.com/news-releases/news-release-details/lilly-acquire-kelonia-therapeutics-advance-vivo-car-t-cell","Credible Press Release URL":"https://www.prnewswire.com/news-releases/lilly-to-acquire-kelonia-therapeutics-to-advance-in-vivo-car-t-cell-therapies-302747122.html"}', 2, 'new', 'High', 'Verified', 'https://investor.lilly.com/news-releases/news-release-details/lilly-acquire-kelonia-therapeutics-advance-vivo-car-t-cell', 'https://www.prnewswire.com/news-releases/lilly-to-acquire-kelonia-therapeutics-to-advance-in-vivo-car-t-cell-therapies-302747122.html', NULL, '2026-09-04');
INSERT INTO records (id, version_id, module, record_key, data_json, row_order, change_type, confidence_level, validation_status, primary_source_url, independent_source_url, source_date, verification_date) VALUES (60, 1, 'technology_intelligence', 'Fusogen-based', '{"Delivery Class":"Fusogen-based","Companies":"Sana Biotechnology","Payload Persistence":"Long-term (integration-dependent design)","Mechanism Summary":"Engineered viral fusogen proteins enable targeted, hypoimmune cell entry without full lentiviral machinery","Key Advantage(s) Claimed":"Potential for reduced immunogenicity","Key Risk(s) Considered":"Earliest-stage; no disclosed in vivo CAR-T clinical asset yet","Representative Asset":"SG293 (preclinical)","Company Announcement URL":"https://ir.sana.com/news-releases/news-release-details/sana-biotechnology-presents-preclinical-data-vivo-car-t-cell","Credible Press Release URL":"https://ir.sana.com/news-releases/news-release-details/sana-biotechnology-announces-oral-presentation-highlighting"}', 3, 'new', 'High', 'Verified', 'https://ir.sana.com/news-releases/news-release-details/sana-biotechnology-presents-preclinical-data-vivo-car-t-cell', 'https://ir.sana.com/news-releases/news-release-details/sana-biotechnology-announces-oral-presentation-highlighting', NULL, '2026-09-04');
INSERT INTO records (id, version_id, module, record_key, data_json, row_order, change_type, confidence_level, validation_status, primary_source_url, independent_source_url, source_date, verification_date) VALUES (61, 1, 'technology_intelligence', 'RNA/LNP (China-based programs)', '{"Delivery Class":"RNA/LNP (China-based programs)","Companies":"Starna Therapeutics, MagicRNA, Genocury Biotech, Immorna","Payload Persistence":"Transient","Mechanism Summary":"LNP-formulated mRNA/RNA CAR constructs, largely autoimmune-focused early programs","Key Advantage(s) Claimed":"Fast, capital-efficient path to first-in-human data","Key Risk(s) Considered":"Smaller company scale; data sets very early (n<10)","Representative Asset":"STR-P004 (Starna), HN2301 (MagicRNA), JY231 (Genocury), JCXH-213 (Immorna)","Company Announcement URL":"https://biopharmaapac.com/news/69/7099/starna-therapeutics-secures-over-rmb-300-million-in-series-b-financing-to-accelerate-in-vivo-car-t-innovation.html","Credible Press Release URL":"https://endpoints.news/starna-therapeutics-raises-44m-to-advance-in-vivo-car-t-programs-after-early-clinical-data/"}', 4, 'new', 'High', 'Verified', 'https://biopharmaapac.com/news/69/7099/starna-therapeutics-secures-over-rmb-300-million-in-series-b-financing-to-accelerate-in-vivo-car-t-innovation.html', 'https://endpoints.news/starna-therapeutics-raises-44m-to-advance-in-vivo-car-t-programs-after-early-clinical-data/', NULL, '2026-09-04');
INSERT INTO records (id, version_id, module, record_key, data_json, row_order, change_type, confidence_level, validation_status, primary_source_url, independent_source_url, source_date, verification_date) VALUES (62, 1, 'technology_intelligence', 'LNP + DNA (non-viral, stable integration)', '{"Delivery Class":"LNP + DNA (non-viral, stable integration)","Companies":"NanoCell Therapeutics","Payload Persistence":"Long-term (transposase-mediated genomic integration)","Mechanism Summary":"Cell-targeted lipid nanoparticle (tLNP) delivers DNA plasmid + transposase system, achieving stable CAR integration without a viral vector","Key Advantage(s) Claimed":"Combines LNP''s non-viral simplicity with lentiviral-like durability; avoids insertional mutagenesis profile concerns of lentivirus","Key Risk(s) Considered":"Earliest-stage; preclinical only, no in vivo CAR-T clinical asset yet","Representative Asset":"NCTX-01 (CD19 x CD22 dual, preclinical)","Company Announcement URL":"https://nanocelltx.com/technology/","Credible Press Release URL":"https://www.biopharminternational.com/view/nanocell-lnp-platform-shows-promise-in-vivo-car-t-development"}', 5, 'new', 'High', 'Verified', 'https://nanocelltx.com/technology/', 'https://www.biopharminternational.com/view/nanocell-lnp-platform-shows-promise-in-vivo-car-t-development', NULL, '2026-09-04');
INSERT INTO records (id, version_id, module, record_key, data_json, row_order, change_type, confidence_level, validation_status, primary_source_url, independent_source_url, source_date, verification_date) VALUES (63, 1, 'technology_intelligence', 'AAV + EDV (site-specific gene editing)', '{"Delivery Class":"AAV + EDV (site-specific gene editing)","Companies":"Azalea Therapeutics","Payload Persistence":"Long-term (CRISPR-Cas9 site-specific genomic integration at TRAC locus)","Mechanism Summary":"Enveloped Delivery Vehicle (EDV) delivers Cas9 RNP to T cells; a T cell-tropic AAV co-delivers a promoterless CAR template for insertion at the endogenous TRAC locus","Key Advantage(s) Claimed":"Physiologic, TRAC-promoter-regulated CAR expression; avoids random integration risk of lentivirus","Key Risk(s) Considered":"Earliest-stage; first-in-primate data only (May 2026), no clinical asset named yet","Representative Asset":"Undisclosed (TRAC-CAR-T lead, preclinical)","Company Announcement URL":"https://azaleatx.com/","Credible Press Release URL":"https://www.globenewswire.com/news-release/2025/11/04/3180290/0/en/Azalea-Therapeutics-Launches-with-82-Million-Financing-to-Redefine-Precision-Genomic-Medicines-by-Engineering-Cells-Directly-Inside-Each-Patient.html"}', 6, 'new', 'High', 'Verified', 'https://azaleatx.com/', 'https://www.globenewswire.com/news-release/2025/11/04/3180290/0/en/Azalea-Therapeutics-Launches-with-82-Million-Financing-to-Redefine-Precision-Genomic-Medicines-by-Engineering-Cells-Directly-Inside-Each-Patient.html', NULL, '2026-09-04');
INSERT INTO records (id, version_id, module, record_key, data_json, row_order, change_type, confidence_level, validation_status, primary_source_url, independent_source_url, source_date, verification_date) VALUES (64, 1, 'target_landscape', 'CD19', '{"Target Antigen":"CD19","# Companies Targeting (named)":12,"Companies":"Capstan Therapeutics, Umoja Biopharma, Orna Therapeutics, Interius BioTherapeutics (INT2106), CREATE Medicines (CRT-402), Genocury Biotech (JY231), MagicRNA (HN2301), Immorna (JCXH-213), Orbital Therapeutics (OTX-201, preclinical), Sana Biotechnology (SG293, preclinical), Vivacta Bio (GT801), Starna Therapeutics (STR-P004)","Disease Category":"Autoimmune (B-cell) / Oncology","Phase (most advanced)":"Phase 1 dosing (Capstan CPTX2309, MagicRNA HN2301, Umoja UB-VV111, Immorna JCXH-213, Vivacta GT801, Orna ORN-252 [healthy volunteers]); CREATE CRT-402 Phase 1/2 (approved, pre-dosing)","White Space Note":"Most crowded in vivo target; mirrors ex vivo CD19 dominance. Note: Interius INT2104 targets CD20 via CD7-targeted vector (CD7 is the vector ligand, not the CAR target)","Company Announcement URL":"https://news.abbvie.com/2025-06-30-AbbVie-to-Acquire-Capstan-Therapeutics,-Further-Strengthening-Commitment-to-Transforming-Patient-Care-in-Immunology","Credible Press Release URL":"https://www.prnewswire.com/news-releases/lilly-to-acquire-orna-therapeutics-to-advance-cell-therapies-302682157.html"}', 0, 'new', 'High', 'Verified', 'https://news.abbvie.com/2025-06-30-AbbVie-to-Acquire-Capstan-Therapeutics,-Further-Strengthening-Commitment-to-Transforming-Patient-Care-in-Immunology', 'https://www.prnewswire.com/news-releases/lilly-to-acquire-orna-therapeutics-to-advance-cell-therapies-302682157.html', NULL, '2026-09-04');
