INSERT INTO records (id, version_id, module, record_key, data_json, row_order, change_type, confidence_level, validation_status, primary_source_url, independent_source_url, source_date, verification_date) VALUES (71, 1, 'target_landscape', 'Undisclosed / platform-stage', '{"Target Antigen":"Undisclosed / platform-stage","# Companies Targeting (named)":3,"Companies":"Pregene Biopharma, Azalea Therapeutics (TRAC-CAR-T lead, preclinical), Korecyte Bio (KOR101, preclinical; hypoxia-activated switch, pan-solid-tumor)","Disease Category":"Oncology / Autoimmune (unspecified)","Phase (most advanced)":"Preclinical to early clinical (IIT)","White Space Note":"Korecyte Bio (KOR101, preclinical) is the first identified in vivo CAR-T program targeting solid tumors — via a hypoxia-activated switch rather than a single named antigen (counted in the Undisclosed/platform-stage row above). Remaining white space: no in vivo program has disclosed a specific solid-tumor ANTIGEN target (e.g., mesothelin, HER2, CLDN18.2). Note: CREATE Medicines'' MT-304 targets HER2, but is a CAR-myeloid/multi-immune program, not CAR-T (see Pipeline Dashboard scope note) — it does not fill this white space. GPRC5D is excluded from this solid-tumor list; it is a plasma-cell antigen targeted for multiple myeloma (hematologic), not a solid-tumor antigen — see rows 10/BCMA x GPRC5D above.","Company Announcement URL":"https://www.fiercebiotech.com/biotech/kite-puts-16b-line-pair-chinas-pregene-another-vivo-car-t-deal","Credible Press Release URL":"https://endpoints.news/starna-therapeutics-raises-44m-to-advance-in-vivo-car-t-programs-after-early-clinical-data/"}', 7, 'new', 'High', 'Verified', 'https://www.fiercebiotech.com/biotech/kite-puts-16b-line-pair-chinas-pregene-another-vivo-car-t-deal', 'https://endpoints.news/starna-therapeutics-raises-44m-to-advance-in-vivo-car-t-programs-after-early-clinical-data/', NULL, '2026-09-04');
