INSERT INTO records (id, version_id, module, record_key, data_json, row_order, change_type, confidence_level, validation_status, primary_source_url, independent_source_url, source_date, verification_date) VALUES (144, 1, 'competitive_intelligence', 'Legend Biotech', '{"Company":"Legend Biotech","Parent (if acquired)":"Independent (public)","Delivery Platform":"Lentiviral (TaVec)","Clinical Progress":"Phase 1 (LB2501); 100% ORR at DL2 (EHA 2026, n=12)","Manufacturing Readiness":"Public company; broader approved cell-therapy franchise","Strategic Camp":"Independent — largest standalone cell therapy company","Key Differentiator":"First-in-class CD19/CD20 dual-targeting in vivo CAR-T; no DLTs/SAEs/deaths; favorable safety vs. peers","Company Announcement URL":"https://investors.legendbiotech.com/news-releases/news-release-details/legend-biotech-announces-late-breaking-oral-presentation-eha","Credible Press Release URL":"https://www.globenewswire.com/news-release/2026/06/02/3305321/0/en/legend-biotech-announces-late-breaking-oral-presentation-at-eha-2026-showcasing-initial-phase-1-in-vivo-car-t-data-with-lb2501-in-non-hodgkin-lymphoma-nhl.html"}', 9, 'new', 'High', 'Verified', 'https://investors.legendbiotech.com/news-releases/news-release-details/legend-biotech-announces-late-breaking-oral-presentation-eha', 'https://www.globenewswire.com/news-release/2026/06/02/3305321/0/en/legend-biotech-announces-late-breaking-oral-presentation-at-eha-2026-showcasing-initial-phase-1-in-vivo-car-t-data-with-lb2501-in-non-hodgkin-lymphoma-nhl.html', NULL, '2026-09-04');
