INSERT INTO records (id, version_id, module, record_key, data_json, row_order, change_type, confidence_level, validation_status, primary_source_url, independent_source_url, source_date, verification_date) VALUES (150, 1, 'competitive_intelligence', 'NanoCell Therapeutics', '{"Company":"NanoCell Therapeutics","Parent (if acquired)":"Independent","Delivery Platform":"tLNP non-viral DNA in vivo CAR-T (NCtx, transposase integration)","Clinical Progress":"Preclinical (CAR.CD22); IMPD filing initiated in Europe","Manufacturing Readiness":"Undisclosed","Strategic Camp":"Independent — preclinical, transatlantic (US/Netherlands)","Key Differentiator":"Only tracked program combining LNP delivery with durable (transposase-mediated) integration, avoiding viral vectors; partnered with OneChain Immunotherapeutics for the CD22 CAR","Company Announcement URL":"https://nanocelltx.com/technology/","Credible Press Release URL":"https://www.biopharminternational.com/view/nanocell-lnp-platform-shows-promise-in-vivo-car-t-development"}', 15, 'new', 'High', 'Verified', 'https://nanocelltx.com/technology/', 'https://www.biopharminternational.com/view/nanocell-lnp-platform-shows-promise-in-vivo-car-t-development', NULL, '2026-09-04');
INSERT INTO records (id, version_id, module, record_key, data_json, row_order, change_type, confidence_level, validation_status, primary_source_url, independent_source_url, source_date, verification_date) VALUES (151, 1, 'competitive_intelligence', 'Azalea Therapeutics', '{"Company":"Azalea Therapeutics","Parent (if acquired)":"Independent","Delivery Platform":"TRAC-locus in vivo CAR-T (EDV + AAV, CRISPR-Cas9)","Clinical Progress":"Preclinical; first-in-primate data (May 2026), no clinical asset named yet","Manufacturing Readiness":"Undisclosed","Strategic Camp":"Independent — preclinical, backed by Third Rock Ventures","Key Differentiator":"Only tracked program using CRISPR-Cas9 site-specific genomic integration (TRAC locus) rather than random integration or transient RNA; $82M launch financing (Nov 2025)","Company Announcement URL":"https://azaleatx.com/","Credible Press Release URL":"https://www.globenewswire.com/news-release/2025/11/04/3180290/0/en/Azalea-Therapeutics-Launches-with-82-Million-Financing-to-Redefine-Precision-Genomic-Medicines-by-Engineering-Cells-Directly-Inside-Each-Patient.html"}', 16, 'new', 'High', 'Verified', 'https://azaleatx.com/', 'https://www.globenewswire.com/news-release/2025/11/04/3180290/0/en/Azalea-Therapeutics-Launches-with-82-Million-Financing-to-Redefine-Precision-Genomic-Medicines-by-Engineering-Cells-Directly-Inside-Each-Patient.html', NULL, '2026-09-04');
