INSERT INTO change_log (version_id, module, record_key, change_type, previous_data_json, new_data_json, field_diffs_json) VALUES (1, 'pipeline_dashboard', 'Immorna|JCXH-213', 'new', NULL, '{"Asset Name":"JCXH-213","Company":"Immorna","Target Antigen":"CD19","Delivery Technology":"LNP (tLCNP, CD8 nanobody-targeted)","Vector / Payload":"mRNA / self-replicating RNA (transient)","Primary Indication":"Systemic sclerosis; enrolling SLE and immune thrombocytopenic purpura (ITP)","Disease Category":"Autoimmune","Development Stage":"Phase 1","Trial Status / Notes":"JCXH-213 first-in-human dosing announced Mar 2025; Apr 2026 update reported deep tissue (lymph-node) B-cell depletion in a systemic sclerosis patient — a first for in vivo CAR-T; peripheral B-cells undetectable; no CRS or liver-enzyme abnormalities; autoantibody titers declined","CAR Generation":"Undisclosed","Company Announcement URL":"https://www.immornabio.com/","Credible Press Release URL":"https://endpoints.news/in-vivo-car-t-race-for-autoimmune-grows-as-two-rna-startups-enter-the-clinic/"}', NULL);
INSERT INTO change_log (version_id, module, record_key, change_type, previous_data_json, new_data_json, field_diffs_json) VALUES (1, 'pipeline_dashboard', 'MagicRNA|HN2301', 'new', NULL, '{"Asset Name":"HN2301","Company":"MagicRNA","Target Antigen":"CD19","Delivery Technology":"LNP (EnC-LNP, cell-targeted)","Vector / Payload":"mRNA (transient)","Primary Indication":"Systemic lupus erythematosus (SLE)","Disease Category":"Autoimmune","Development Stage":"Phase 1","Trial Status / Notes":"n=5 refractory SLE (4 with lupus nephritis), published in NEJM (Sep 2025); up to 60% CD8+ CAR+ T-cell reprogramming at higher dose; complete circulating B-cell depletion persisting 7-10 days; SLEDAI reduction up to 20 points at 3 months; no neurotoxicity or SAEs","CAR Generation":"Undisclosed","Company Announcement URL":"https://www.magicrna.com/","Credible Press Release URL":"https://www.biospace.com/press-releases/magicrnas-first-in-human-clinical-data-demonstrating-feasibility-of-in-vivo-car-t-therapy-in-systemic-lupus-erythematosus-published-in-the-new-england-journal-of-medicine"}', NULL);
