INSERT INTO change_log (version_id, module, record_key, change_type, previous_data_json, new_data_json, field_diffs_json) VALUES (1, 'pipeline_dashboard', 'Umoja Biopharma|UB-VV500', 'new', NULL, '{"Asset Name":"UB-VV500","Company":"Umoja Biopharma","Target Antigen":"BCMA x GPRC5D (dual-targeting)","Delivery Technology":"Lentiviral (VivoVec)","Vector / Payload":"Surface-engineered lentiviral vector; potency-enhanced","Primary Indication":"Relapsed/refractory multiple myeloma","Disease Category":"Oncology","Development Stage":"Phase 1","Trial Status / Notes":"Industry''s first combination BCMA x GPRC5D in vivo CAR-T; preclinical data at ASGCT 2026 (poster #2046, May 13 2026); Phase 1 dose-finding study with rapamycin in r/r MM registered Aug 2026 (NCT07735546, est. 100 patients); Umoja guided clinic entry toward end-2026","CAR Generation":"Undisclosed","Company Announcement URL":"https://www.globenewswire.com/news-release/2026/04/27/3282054/0/en/umoja-biopharma-announces-unveiling-of-ub-vv500-in-upcoming-poster-presentation-at-the-american-society-of-gene-cell-therapy-annual-meeting.html","Credible Press Release URL":"https://www.biospace.com/press-releases/umoja-biopharma-announces-unveiling-of-ub-vv500-in-upcoming-poster-presentation-at-the-american-society-of-gene-cell-therapy-annual-meeting"}', NULL);
INSERT INTO change_log (version_id, module, record_key, change_type, previous_data_json, new_data_json, field_diffs_json) VALUES (1, 'pipeline_dashboard', 'Sana Biotechnology|SG227', 'new', NULL, '{"Asset Name":"SG227","Company":"Sana Biotechnology","Target Antigen":"BCMA","Delivery Technology":"Fusogen-based (fusosome)","Vector / Payload":"CD8-targeted fusosome delivering a BCMA-directed CAR","Primary Indication":"Multiple myeloma","Disease Category":"Oncology","Development Stage":"IND-enabling","Trial Status / Notes":"Second fusogen program behind SG293; Sana guides clinic entry as early as mid-2027; no clinical data disclosed","CAR Generation":"Undisclosed","Company Announcement URL":"https://ir.sana.com/news-releases/news-release-details/sana-biotechnology-presents-preclinical-data-vivo-car-t-cell","Credible Press Release URL":"https://www.globenewswire.com/news-release/2026/05/12/3293377/0/en/Sana-Biotechnology-Presents-Preclinical-Data-for-In-Vivo-CAR-T-Cell-Therapy-SG293-Surrogate-Demonstrating-Cell-Specific-Delivery-Potent-CAR-T-Cell-Generation-and-Deep-B-Cell-Deplet.html"}', NULL);
