INSERT INTO change_log (version_id, module, record_key, change_type, previous_data_json, new_data_json, field_diffs_json) VALUES (1, 'pipeline_dashboard', 'Starna Therapeutics|STR-P004', 'new', NULL, '{"Asset Name":"STR-P004","Company":"Starna Therapeutics","Target Antigen":"CD19","Delivery Technology":"LNP (tLNP; ionizable lipid conjugated to a CD8-targeting ligand)","Vector / Payload":"mRNA (transient, repeat-dose)","Primary Indication":"Autoimmune (SLE); oncology (NHL) — IIT","Disease Category":"Autoimmune / Oncology","Development Stage":"Phase 1","Trial Status / Notes":"Autoimmune IIT dosed 0.03-0.1 mg/kg, up to 8 infusions (TITE-BOIN12 design), patients treated Sep 1 2025 - Jan 20 2026, presented at ASCO 2026; registered Phase 1 in r/r B-cell NHL (NCT07003178); Series B Oct 2025 (RMB 300M / ~$44M) earmarked for in vivo CAR-T advancement","CAR Generation":"Undisclosed","Company Announcement URL":"https://endpoints.news/starna-therapeutics-raises-44m-to-advance-in-vivo-car-t-programs-after-early-clinical-data/","Credible Press Release URL":"https://ascopubs.org/doi/pdfdirect/10.1200/JCO.2026.44.16_suppl.e14519"}', NULL);
