INSERT INTO change_log (version_id, module, record_key, change_type, previous_data_json, new_data_json, field_diffs_json) VALUES (1, 'pipeline_dashboard', 'NanoCell Therapeutics|NCTX-01', 'new', NULL, '{"Asset Name":"NCTX-01","Company":"NanoCell Therapeutics","Target Antigen":"CD19 x CD22 (dual CAR)","Delivery Technology":"tLNP (NCtx; non-viral, DNA-based)","Vector / Payload":"DNA (transposase, stable integration)","Primary Indication":"B-cell malignancies (DLBCL, follicular lymphoma)","Disease Category":"Oncology","Development Stage":"Preclinical (IMPD filing initiated in Europe)","Trial Status / Notes":"Non-viral DNA-delivering tLNP platform (NCtx); partnered with OneChain Immunotherapeutics for the CD22 CAR","CAR Generation":"Undisclosed","Company Announcement URL":"https://nanocelltx.com/technology/","Credible Press Release URL":"https://www.biopharminternational.com/view/nanocell-lnp-platform-shows-promise-in-vivo-car-t-development"}', NULL);
INSERT INTO change_log (version_id, module, record_key, change_type, previous_data_json, new_data_json, field_diffs_json) VALUES (1, 'pipeline_dashboard', 'Azalea Therapeutics|Undisclosed (TRAC-CAR-T lead)', 'new', NULL, '{"Asset Name":"Undisclosed (TRAC-CAR-T lead)","Company":"Azalea Therapeutics","Target Antigen":"Undisclosed","Delivery Technology":"AAV / EDV (Enveloped Delivery Vehicle)","Vector / Payload":"DNA (CRISPR-Cas9 site-specific integration, TRAC locus)","Primary Indication":"Undisclosed (oncology + autoimmune)","Disease Category":"Autoimmune / Oncology","Development Stage":"Preclinical (first-in-primate data, May 2026)","Trial Status / Notes":"TRAC-locus in vivo CAR-T via dual-vector EDV+AAV; $82M launch financing (Nov 2025); no clinical asset named yet","CAR Generation":"Undisclosed","Company Announcement URL":"https://azaleatx.com/","Credible Press Release URL":"https://www.globenewswire.com/news-release/2025/11/04/3180290/0/en/Azalea-Therapeutics-Launches-with-82-Million-Financing-to-Redefine-Precision-Genomic-Medicines-by-Engineering-Cells-Directly-Inside-Each-Patient.html"}', NULL);
INSERT INTO change_log (version_id, module, record_key, change_type, previous_data_json, new_data_json, field_diffs_json) VALUES (1, 'pipeline_dashboard', 'Korecyte Bio|KOR101', 'new', NULL, '{"Asset Name":"KOR101","Company":"Korecyte Bio","Target Antigen":"Undisclosed (broadly-targeting CAR + hypoxia switch, pan-solid-tumor)","Delivery Technology":"Lentiviral (in vivo transduction)","Vector / Payload":"DNA (stable integration)","Primary Indication":"Solid tumors (pan-cancer)","Disease Category":"Oncology","Development Stage":"Preclinical","Trial Status / Notes":"HypoxiCAR platform: hypoxia-sensing genetic switch keeps CAR-T cells dormant until they enter a low-oxygen solid tumour microenvironment; King''s College London spin-out with CGT Catapult seed investment via the Innovate UK Cross-Catapult Investment Pilot (May 2026); only solid-tumour-focused in vivo CAR-T in this tracker","CAR Generation":"Undisclosed","Company Announcement URL":"https://korecyte.com/technology/","Credible Press Release URL":"https://www.bioprocessintl.com/deal-making/cgt-catapult-teams-with-korecyte-bio-on-low-oxygen-car-t-platform"}', NULL);
INSERT INTO change_log (version_id, module, record_key, change_type, previous_data_json, new_data_json, field_diffs_json) VALUES (1, 'clinical_intelligence', 'Kelonia Therapeutics|KLN-1010', 'new', NULL, '{"Asset":"KLN-1010","Company":"Kelonia Therapeutics","Indication":"r/r multiple myeloma","n (reported)":18,"ORR / Response":"100% ORR; MRD-neg at 1 mo in all evaluable pts; 4 sCR + 2 VGPR among 6 pts with ≥4 mo follow-up; first pt MRD-neg >10 mo","CRS":"16/18 pts CRS, all Grade 1-2","ICANS":"1 Grade 1 + 1 Grade 3 (Gr3 limited to 3 days)","Deaths":"0","Notable Efficacy/Safety Note":"No lymphodepletion required; FDA Fast Track granted May 2026; dose-dependent in vivo CAR-T expansion and persistence; consistent with outpatient dosing","Company Announcement URL":"https://investor.lilly.com/news-releases/news-release-details/lilly-acquire-kelonia-therapeutics-advance-vivo-car-t-cell","Credible Press Release URL":"https://www.prnewswire.com/news-releases/lilly-to-acquire-kelonia-therapeutics-to-advance-in-vivo-car-t-cell-therapies-302747122.html"}', NULL);
INSERT INTO change_log (version_id, module, record_key, change_type, previous_data_json, new_data_json, field_diffs_json) VALUES (1, 'clinical_intelligence', 'EsoBiotec|ESO-T01', 'new', NULL, '{"Asset":"ESO-T01","Company":"EsoBiotec","Indication":"Multiple myeloma","n (reported)":"5 (published cohort, Nature Medicine)","ORR / Response":"4/5 objective response; 3 stringent CR; MRD-neg (10^-5) in all 4 evaluable responders by day 60","CRS":"CRS in 4/5 pts (3 Grade 3, 1 Grade 2); biphasic pattern — innate-immune surge <24h pre-dating detectable CAR-T, then a second CAR-T-driven wave; all 5 pts experienced Grade ≥3 adverse events, though no dose-limiting toxicities were reported","ICANS":"1 case (Grade 1)","Deaths":"1 — attributed by investigators to disease progression (extramedullary lesion causing spinal cord compression), not treatment","Notable Efficacy/Safety Note":"Peer-reviewed Phase 1 (n=5) published in Nature Medicine, Mar 2026; no dose-limiting toxicities; highest-severity safety signal reported among in vivo CAR-T assets to date, though death not attributed to therapy","Company Announcement URL":"https://www.astrazeneca.com/media-centre/press-releases/2025/acquisition-of-esobiotec-completed.html","Credible Press Release URL":"https://www.biopharminternational.com/view/astrazeneca-acquire-esobiotec-boosting-cell-therapy-portfolio"}', NULL);
INSERT INTO change_log (version_id, module, record_key, change_type, previous_data_json, new_data_json, field_diffs_json) VALUES (1, 'clinical_intelligence', 'Interius BioTherapeutics|INT2104', 'new', NULL, '{"Asset":"INT2104","Company":"Interius BioTherapeutics","Indication":"B-cell malignancies","n (reported)":"Undisclosed","ORR / Response":"Undisclosed","CRS":"Undisclosed","ICANS":"Undisclosed","Deaths":"Undisclosed","Notable Efficacy/Safety Note":"First-in-human dosing in Australia (Oct 2024, INVISE trial); Phase 1 expanded into Europe (Germany/PEI) Jan 2025; data maturing","Company Announcement URL":"https://www.gilead.com/news/news-details/2025/kite-to-acquire-interius-biotherapeutics-to-advance-in-vivo-platform","Credible Press Release URL":"https://www.prnewswire.com/news-releases/interius-biotherapeutics-receives-hrec-approval-and-ctn-clearance-from-the-tga-to-commence-a-phase-1-clinical-trial-for-its-first-in-class-in-vivo-car-therapeutic-for-b-cell-malignancies-302191433.html"}', NULL);
INSERT INTO change_log (version_id, module, record_key, change_type, previous_data_json, new_data_json, field_diffs_json) VALUES (1, 'clinical_intelligence', 'MagicRNA|HN2301', 'new', NULL, '{"Asset":"HN2301","Company":"MagicRNA","Indication":"Systemic lupus erythematosus (SLE) - 4 of 5 patients also had lupus nephritis","n (reported)":5,"ORR / Response":"Up to 60% CD8+ CAR+ T-cell reprogramming at LOW dose; complete depletion of circulating B cells; SLEDAI score reduction up to 20 points within 3 months","CRS":"None significant reported","ICANS":"None significant reported","Deaths":"0","Notable Efficacy/Safety Note":"Published in NEJM (Sep 2025) - first-ever peer-reviewed clinical data for an mRNA-LNP in vivo CAR-T; no neurotoxicity, no SAEs, no clinically significant liver enzyme elevation in any of 5 patients. Follow-on data showing TISSUE-level B-cell depletion presented as an ASGCT 2026 oral (13 May 2026) and at EULAR 2026 (June 2026).","Company Announcement URL":"https://www.magicrna.com/company/114.html","Credible Press Release URL":"https://www.biospace.com/press-releases/magicrnas-first-in-human-clinical-data-demonstrating-feasibility-of-in-vivo-car-t-therapy-in-systemic-lupus-erythematosus-published-in-the-new-england-journal-of-medicine"}', NULL);
INSERT INTO change_log (version_id, module, record_key, change_type, previous_data_json, new_data_json, field_diffs_json) VALUES (1, 'clinical_intelligence', 'Umoja Biopharma|UB-VV111 / UB-VV100', 'new', NULL, '{"Asset":"UB-VV111 / UB-VV100","Company":"Umoja Biopharma","Indication":"B-cell malignancies","n (reported)":"Undisclosed","ORR / Response":"Undisclosed","CRS":"Undisclosed","ICANS":"Undisclosed","Deaths":"Undisclosed","Notable Efficacy/Safety Note":"FDA Fast Track granted on strength of preclinical/early package","Company Announcement URL":"https://www.umoja-biopharma.com/news/umoja-biopharma-announces-that-ub-vv111-receives-fda-fast-track-designation-for-relapsed-refractory-b-cell-malignancies/","Credible Press Release URL":"https://www.onclive.com/view/fda-grants-fast-track-designation-to-ub-vv111-for-r-r-b-cell-malignancies"}', NULL);
INSERT INTO change_log (version_id, module, record_key, change_type, previous_data_json, new_data_json, field_diffs_json) VALUES (1, 'clinical_intelligence', 'Legend Biotech|LB2501', 'new', NULL, '{"Asset":"LB2501","Company":"Legend Biotech","Indication":"R/R B-cell non-Hodgkin lymphoma (B-NHL)","n (reported)":12,"ORR / Response":"100% ORR (6/6) at DL2; CR 83.3% (5/6); all responses ongoing at cutoff","CRS":"66.7% patients, all ≤ Grade 2","ICANS":"None reported","Deaths":0,"Notable Efficacy/Safety Note":"First-in-class CD19/CD20 dual-targeting in vivo CAR-T; no DLTs, SAEs, or ICANS; no lymphodepletion required; dose-dependent CAR-T expansion. Preliminary Phase 1 / early clinical proof-of-concept only (n=12, Apr 1 2026 data cutoff) — directional, not powered for conclusions.","Company Announcement URL":"https://investors.legendbiotech.com/news-releases/news-release-details/legend-biotech-announces-late-breaking-oral-presentation-eha","Credible Press Release URL":"https://www.globenewswire.com/news-release/2026/06/02/3305321/0/en/legend-biotech-announces-late-breaking-oral-presentation-at-eha-2026-showcasing-initial-phase-1-in-vivo-car-t-data-with-lb2501-in-non-hodgkin-lymphoma-nhl.html"}', NULL);
INSERT INTO change_log (version_id, module, record_key, change_type, previous_data_json, new_data_json, field_diffs_json) VALUES (1, 'clinical_intelligence', 'Genocury Biotech|JY231 (Genocury)', 'new', NULL, '{"Asset":"JY231 (Genocury)","Company":"Genocury Biotech","Indication":"R/R diffuse large B-cell lymphoma (DLBCL)","n (reported)":1,"ORR / Response":"Complete remission (CR) at 28 days; durable response sustained through 90-day follow-up","CRS":"None reported","ICANS":"None reported","Deaths":0,"Notable Efficacy/Safety Note":"Early human in vivo CAR-T efficacy signal — single R/R DLBCL case (investigator-initiated; company release Apr 2025): CR at 28 days, sustained through 90-day follow-up; no lymphodepletion required","Company Announcement URL":"https://www.prnewswire.com/news-releases/genocury-biotech-annouces-groundbreaking-advance-in-relapsedrefractory-dlbcl-through-pioneering-in-vivo-cd19-car-t-therapy-302442371.html","Credible Press Release URL":"https://www.curetoday.com/view/in-vivo-cd19-car-t-leads-to-remission-in-dlbcl-without-lymphodepletion"}', NULL);
INSERT INTO change_log (version_id, module, record_key, change_type, previous_data_json, new_data_json, field_diffs_json) VALUES (1, 'clinical_intelligence', 'Immorna|JCXH-213', 'new', NULL, '{"Asset":"JCXH-213","Company":"Immorna","Indication":"Systemic sclerosis","n (reported)":1,"ORR / Response":"Peripheral B-cells undetectable through 2-week observation window; first tissue (lymph node biopsy)-level B-cell depletion shown for an in vivo CAR-T; autoantibody titers declined","CRS":"None reported","ICANS":"None reported","Deaths":0,"Notable Efficacy/Safety Note":"First-in-human dosing announced Mar 2025; Apr 2026 update reported deep tissue (lymph-node) B-cell depletion in a systemic sclerosis patient — a first for in vivo CAR-T; no CRS or liver-enzyme abnormalities observed","Company Announcement URL":"https://www.immornabio.com/","Credible Press Release URL":"https://endpoints.news/in-vivo-car-t-race-for-autoimmune-grows-as-two-rna-startups-enter-the-clinic/"}', NULL);
INSERT INTO change_log (version_id, module, record_key, change_type, previous_data_json, new_data_json, field_diffs_json) VALUES (1, 'clinical_intelligence', 'Vivacta Bio|GT801', 'new', NULL, '{"Asset":"GT801","Company":"Vivacta Bio","Indication":"R/R CD19+ B-cell malignancies (NHL)","n (reported)":"Undisclosed (early IIT cohort)","ORR / Response":"Encouraging early clinical activity reported (efficient CAR expression, deep B-cell depletion); specific ORR/CR figures not disclosed in the English-language release","CRS":"Preclinical data reported minimal cytokine release (IL-6, TNF-α); clinical CRS data for the human cohort not yet disclosed","ICANS":"Undisclosed","Deaths":"Undisclosed","Notable Efficacy/Safety Note":"T-LNP (CLAMP)-delivered mRNA CD19 CAR-T; >30-fold in vivo CAR-T expansion reported preclinically; first-in-human data presented at ASH 2025 (oral session)","Company Announcement URL":"https://www.prnewswire.com/news-releases/vivacta-bio-closed-series-a-and-series-a-financing-of-over-us50-million-302756983.html","Credible Press Release URL":"https://www.prnewswire.com/news-releases/vivacta-bio-announces-promising-first-in-human-results-for-gt801-an-in-vivo-car-t-therapy-in-non-hodgkins-lymphoma-at-the-2025-ash-annual-meeting-302633966.html"}', NULL);
INSERT INTO change_log (version_id, module, record_key, change_type, previous_data_json, new_data_json, field_diffs_json) VALUES (1, 'technology_intelligence', 'LNP + mRNA (transient)', 'new', NULL, '{"Delivery Class":"LNP + mRNA (transient)","Companies":"Capstan Therapeutics, CREATE Medicines, Vivacta Bio","Payload Persistence":"Days to weeks (non-integrating)","Mechanism Summary":"Antibody/ligand-decorated lipid nanoparticle delivers CAR-encoding mRNA to circulating T cells","Key Advantage(s) Claimed":"Potentially cleaner safety profile; repeat/titratable dosing possible","Key Risk(s) Considered":"Shorter persistence may limit durability vs. autologous CAR-T","Representative Asset":"CPTX2309, CRT-402, GT801","Company Announcement URL":"https://news.abbvie.com/2025-06-30-AbbVie-to-Acquire-Capstan-Therapeutics,-Further-Strengthening-Commitment-to-Transforming-Patient-Care-in-Immunology","Credible Press Release URL":"https://www.prnewswire.com/news-releases/abbvie-completes-acquisition-of-capstan-therapeutics-302533462.html"}', NULL);
INSERT INTO change_log (version_id, module, record_key, change_type, previous_data_json, new_data_json, field_diffs_json) VALUES (1, 'technology_intelligence', 'LNP + Circular RNA', 'new', NULL, '{"Delivery Class":"LNP + Circular RNA","Companies":"Orna Therapeutics, Orbital Therapeutics","Payload Persistence":"Extended vs. linear mRNA, still non-integrating","Mechanism Summary":"Circular RNA scaffold extends half-life of CAR expression relative to standard mRNA","Key Advantage(s) Claimed":"Longer transient expression window than linear mRNA","Key Risk(s) Considered":"Still non-integrating; durability data limited","Representative Asset":"ORN-252, OTX-201","Company Announcement URL":"https://investor.lilly.com/news-releases/news-release-details/lilly-acquire-orna-therapeutics-advance-cell-therapies","Credible Press Release URL":"https://www.biopharmadive.com/news/bristol-myers-acquire-orbital-in-vivo-cell-therapy/802573/"}', NULL);
INSERT INTO change_log (version_id, module, record_key, change_type, previous_data_json, new_data_json, field_diffs_json) VALUES (1, 'technology_intelligence', 'Lentiviral (stable integration)', 'new', NULL, '{"Delivery Class":"Lentiviral (stable integration)","Companies":"Umoja Biopharma, Interius BioTherapeutics, EsoBiotec, Kelonia Therapeutics, Pregene Biopharma, Legend Biotech, Vyriad, Korecyte Bio","Payload Persistence":"Long-term (genomic integration)","Mechanism Summary":"Engineered, replication-incompetent lentiviral particles with T-cell-targeting envelope proteins (e.g., anti-CD3, anti-CD7, anti-CD8 scFv) deliver CAR-encoding DNA","Key Advantage(s) Claimed":"Persistence intended to mirror autologous CAR-T; single administration","Key Risk(s) Considered":"Insertional mutagenesis / secondary malignancy risk considered a class issue; historically harder to manufacture at scale","Representative Asset":"UB-VV111, INT2104, ESO-T01, KLN-1010, LB2501, VV169, KOR101","Company Announcement URL":"https://investor.lilly.com/news-releases/news-release-details/lilly-acquire-kelonia-therapeutics-advance-vivo-car-t-cell","Credible Press Release URL":"https://www.prnewswire.com/news-releases/lilly-to-acquire-kelonia-therapeutics-to-advance-in-vivo-car-t-cell-therapies-302747122.html"}', NULL);
INSERT INTO change_log (version_id, module, record_key, change_type, previous_data_json, new_data_json, field_diffs_json) VALUES (1, 'technology_intelligence', 'Fusogen-based', 'new', NULL, '{"Delivery Class":"Fusogen-based","Companies":"Sana Biotechnology","Payload Persistence":"Long-term (integration-dependent design)","Mechanism Summary":"Engineered viral fusogen proteins enable targeted, hypoimmune cell entry without full lentiviral machinery","Key Advantage(s) Claimed":"Potential for reduced immunogenicity","Key Risk(s) Considered":"Earliest-stage; no disclosed in vivo CAR-T clinical asset yet","Representative Asset":"SG293 (preclinical)","Company Announcement URL":"https://ir.sana.com/news-releases/news-release-details/sana-biotechnology-presents-preclinical-data-vivo-car-t-cell","Credible Press Release URL":"https://ir.sana.com/news-releases/news-release-details/sana-biotechnology-announces-oral-presentation-highlighting"}', NULL);
INSERT INTO change_log (version_id, module, record_key, change_type, previous_data_json, new_data_json, field_diffs_json) VALUES (1, 'technology_intelligence', 'RNA/LNP (China-based programs)', 'new', NULL, '{"Delivery Class":"RNA/LNP (China-based programs)","Companies":"Starna Therapeutics, MagicRNA, Genocury Biotech, Immorna","Payload Persistence":"Transient","Mechanism Summary":"LNP-formulated mRNA/RNA CAR constructs, largely autoimmune-focused early programs","Key Advantage(s) Claimed":"Fast, capital-efficient path to first-in-human data","Key Risk(s) Considered":"Smaller company scale; data sets very early (n<10)","Representative Asset":"STR-P004 (Starna), HN2301 (MagicRNA), JY231 (Genocury), JCXH-213 (Immorna)","Company Announcement URL":"https://biopharmaapac.com/news/69/7099/starna-therapeutics-secures-over-rmb-300-million-in-series-b-financing-to-accelerate-in-vivo-car-t-innovation.html","Credible Press Release URL":"https://endpoints.news/starna-therapeutics-raises-44m-to-advance-in-vivo-car-t-programs-after-early-clinical-data/"}', NULL);
INSERT INTO change_log (version_id, module, record_key, change_type, previous_data_json, new_data_json, field_diffs_json) VALUES (1, 'technology_intelligence', 'LNP + DNA (non-viral, stable integration)', 'new', NULL, '{"Delivery Class":"LNP + DNA (non-viral, stable integration)","Companies":"NanoCell Therapeutics","Payload Persistence":"Long-term (transposase-mediated genomic integration)","Mechanism Summary":"Cell-targeted lipid nanoparticle (tLNP) delivers DNA plasmid + transposase system, achieving stable CAR integration without a viral vector","Key Advantage(s) Claimed":"Combines LNP''s non-viral simplicity with lentiviral-like durability; avoids insertional mutagenesis profile concerns of lentivirus","Key Risk(s) Considered":"Earliest-stage; preclinical only, no in vivo CAR-T clinical asset yet","Representative Asset":"NCTX-01 (CD19 x CD22 dual, preclinical)","Company Announcement URL":"https://nanocelltx.com/technology/","Credible Press Release URL":"https://www.biopharminternational.com/view/nanocell-lnp-platform-shows-promise-in-vivo-car-t-development"}', NULL);
INSERT INTO change_log (version_id, module, record_key, change_type, previous_data_json, new_data_json, field_diffs_json) VALUES (1, 'technology_intelligence', 'AAV + EDV (site-specific gene editing)', 'new', NULL, '{"Delivery Class":"AAV + EDV (site-specific gene editing)","Companies":"Azalea Therapeutics","Payload Persistence":"Long-term (CRISPR-Cas9 site-specific genomic integration at TRAC locus)","Mechanism Summary":"Enveloped Delivery Vehicle (EDV) delivers Cas9 RNP to T cells; a T cell-tropic AAV co-delivers a promoterless CAR template for insertion at the endogenous TRAC locus","Key Advantage(s) Claimed":"Physiologic, TRAC-promoter-regulated CAR expression; avoids random integration risk of lentivirus","Key Risk(s) Considered":"Earliest-stage; first-in-primate data only (May 2026), no clinical asset named yet","Representative Asset":"Undisclosed (TRAC-CAR-T lead, preclinical)","Company Announcement URL":"https://azaleatx.com/","Credible Press Release URL":"https://www.globenewswire.com/news-release/2025/11/04/3180290/0/en/Azalea-Therapeutics-Launches-with-82-Million-Financing-to-Redefine-Precision-Genomic-Medicines-by-Engineering-Cells-Directly-Inside-Each-Patient.html"}', NULL);
INSERT INTO change_log (version_id, module, record_key, change_type, previous_data_json, new_data_json, field_diffs_json) VALUES (1, 'target_landscape', 'CD19', 'new', NULL, '{"Target Antigen":"CD19","# Companies Targeting (named)":12,"Companies":"Capstan Therapeutics, Umoja Biopharma, Orna Therapeutics, Interius BioTherapeutics (INT2106), CREATE Medicines (CRT-402), Genocury Biotech (JY231), MagicRNA (HN2301), Immorna (JCXH-213), Orbital Therapeutics (OTX-201, preclinical), Sana Biotechnology (SG293, preclinical), Vivacta Bio (GT801), Starna Therapeutics (STR-P004)","Disease Category":"Autoimmune (B-cell) / Oncology","Phase (most advanced)":"Phase 1 dosing (Capstan CPTX2309, MagicRNA HN2301, Umoja UB-VV111, Immorna JCXH-213, Vivacta GT801, Orna ORN-252 [healthy volunteers]); CREATE CRT-402 Phase 1/2 (approved, pre-dosing)","White Space Note":"Most crowded in vivo target; mirrors ex vivo CD19 dominance. Note: Interius INT2104 targets CD20 via CD7-targeted vector (CD7 is the vector ligand, not the CAR target)","Company Announcement URL":"https://news.abbvie.com/2025-06-30-AbbVie-to-Acquire-Capstan-Therapeutics,-Further-Strengthening-Commitment-to-Transforming-Patient-Care-in-Immunology","Credible Press Release URL":"https://www.prnewswire.com/news-releases/lilly-to-acquire-orna-therapeutics-to-advance-cell-therapies-302682157.html"}', NULL);
INSERT INTO change_log (version_id, module, record_key, change_type, previous_data_json, new_data_json, field_diffs_json) VALUES (1, 'target_landscape', 'BCMA', 'new', NULL, '{"Target Antigen":"BCMA","# Companies Targeting (named)":5,"Companies":"Kelonia Therapeutics, EsoBiotec, Vyriad (VV169), Genocury Biotech (JY232), Sana Biotechnology (SG227)","Disease Category":"Oncology (multiple myeloma)","Phase (most advanced)":"Phase 1 (Kelonia KLN-1010, EsoBiotec ESO-T01, Genocury JY232 [NCT07336823, Recruiting]); IND-enabling/Preclinical (Sana SG227, Vyriad VV169)","White Space Note":"Two competing lentiviral approaches; Kelonia ASCO 2026 data (18 pts, 100% ORR) now strongest early signal; EsoBiotec has more mature but riskier profile","Company Announcement URL":"https://investor.lilly.com/news-releases/news-release-details/lilly-acquire-kelonia-therapeutics-advance-vivo-car-t-cell","Credible Press Release URL":"https://www.astrazeneca.com/media-centre/press-releases/2025/acquisition-of-esobiotec-completed.html"}', NULL);
INSERT INTO change_log (version_id, module, record_key, change_type, previous_data_json, new_data_json, field_diffs_json) VALUES (1, 'target_landscape', 'CD20 (single-target)', 'new', NULL, '{"Target Antigen":"CD20 (single-target)","# Companies Targeting (named)":1,"Companies":"Interius BioTherapeutics","Disease Category":"Oncology (B-cell malignancies)","Phase (most advanced)":"Phase 1","White Space Note":"CD7 used as the T-cell homing/targeting ligand on the lentiviral particle, not solely the CAR target","Company Announcement URL":"https://www.gilead.com/news/news-details/2025/kite-to-acquire-interius-biotherapeutics-to-advance-in-vivo-platform","Credible Press Release URL":"https://www.prnewswire.com/news-releases/interius-biotherapeutics-receives-hrec-approval-and-ctn-clearance-from-the-tga-to-commence-a-phase-1-clinical-trial-for-its-first-in-class-in-vivo-car-therapeutic-for-b-cell-malignancies-302191433.html"}', NULL);
INSERT INTO change_log (version_id, module, record_key, change_type, previous_data_json, new_data_json, field_diffs_json) VALUES (1, 'target_landscape', 'CD19/CD20 (dual-targeting)', 'new', NULL, '{"Target Antigen":"CD19/CD20 (dual-targeting)","# Companies Targeting (named)":1,"Companies":"Legend Biotech","Disease Category":"Oncology (B-cell NHL)","Phase (most advanced)":"Phase 1 (LB2501)","White Space Note":"First-in-class CD19/CD20 dual-targeting in vivo CAR-T; 100% ORR at DL2 (6/6), no lymphodepletion required","Company Announcement URL":"https://investors.legendbiotech.com/news-releases/news-release-details/legend-biotech-announces-late-breaking-oral-presentation-eha","Credible Press Release URL":"https://www.globenewswire.com/news-release/2026/06/02/3305321/0/en/legend-biotech-announces-late-breaking-oral-presentation-at-eha-2026-showcasing-initial-phase-1-in-vivo-car-t-data-with-lb2501-in-non-hodgkin-lymphoma-nhl.html"}', NULL);
INSERT INTO change_log (version_id, module, record_key, change_type, previous_data_json, new_data_json, field_diffs_json) VALUES (1, 'target_landscape', 'CD19 x BCMA (dual-targeting)', 'new', NULL, '{"Target Antigen":"CD19 x BCMA (dual-targeting)","# Companies Targeting (named)":1,"Companies":"CREATE Medicines (CRT-403)","Disease Category":"Autoimmune","Phase (most advanced)":"Preclinical","White Space Note":"Dual CD19 x BCMA in vivo CAR intended to broaden reach across refractory autoimmune indications beyond single-antigen B-cell depletion","Company Announcement URL":"https://www.prnewswire.com/news-releases/create-medicines-expands-clinical-in-vivo-car-pipeline-and-lnp-technology-suite-by-forming-strategic-collaboration-with-westgene-302862722.html","Credible Press Release URL":"https://www.biospace.com/press-releases/create-medicines-expands-clinical-in-vivo-car-pipeline-and-lnp-technology-suite-by-forming-strategic-collaboration-with-westgene"}', NULL);
INSERT INTO change_log (version_id, module, record_key, change_type, previous_data_json, new_data_json, field_diffs_json) VALUES (1, 'target_landscape', 'BCMA x GPRC5D (dual-targeting)', 'new', NULL, '{"Target Antigen":"BCMA x GPRC5D (dual-targeting)","# Companies Targeting (named)":1,"Companies":"Umoja Biopharma (UB-VV500)","Disease Category":"Oncology (multiple myeloma)","Phase (most advanced)":"Phase 1 (NCT07735546, dose-finding, r/r MM)","White Space Note":"Industry''s first combination BCMA x GPRC5D in vivo CAR-T; targets two myeloma plasma-cell antigens to reduce single-antigen relapse/escape risk","Company Announcement URL":"https://www.globenewswire.com/news-release/2026/04/27/3282054/0/en/umoja-biopharma-announces-unveiling-of-ub-vv500-in-upcoming-poster-presentation-at-the-american-society-of-gene-cell-therapy-annual-meeting.html","Credible Press Release URL":"https://www.biospace.com/press-releases/umoja-biopharma-announces-unveiling-of-ub-vv500-in-upcoming-poster-presentation-at-the-american-society-of-gene-cell-therapy-annual-meeting"}', NULL);
INSERT INTO change_log (version_id, module, record_key, change_type, previous_data_json, new_data_json, field_diffs_json) VALUES (1, 'target_landscape', 'CD22', 'new', NULL, '{"Target Antigen":"CD22","# Companies Targeting (named)":2,"Companies":"Umoja Biopharma (UB-VV400), NanoCell Therapeutics (NCTX-01, CD19 x CD22 dual)","Disease Category":"Oncology (B-cell malignancies)","Phase (most advanced)":"Phase 1 (UB-VV400, first patient dosing targeted Q3 2026); NanoCell preclinical","White Space Note":"First-in-class CD22 target in the in vivo CAR-T field — differentiates from CD19-dominant landscape; relevant for CD19-relapsed/antigen-escape patients","Company Announcement URL":"https://www.globenewswire.com/news-release/2026/07/16/3328378/0/en/umoja-biopharma-announces-fda-clearance-of-ind-application-for-ub-vv400-the-industry-s-first-known-cd22-directed-in-vivo-car-t-cell-therapy-for-relapsed-refractory-b-cell-malignanc.html","Credible Press Release URL":"https://www.biospace.com/press-releases/umoja-biopharma-announces-fda-clearance-of-ind-application-for-ub-vv400-the-industrys-first-known-cd22-directed-in-vivo-car-t-cell-therapy-for-relapsed-refractory-b-cell-malignancies"}', NULL);
INSERT INTO change_log (version_id, module, record_key, change_type, previous_data_json, new_data_json, field_diffs_json) VALUES (1, 'target_landscape', 'Undisclosed / platform-stage', 'new', NULL, '{"Target Antigen":"Undisclosed / platform-stage","# Companies Targeting (named)":3,"Companies":"Pregene Biopharma, Azalea Therapeutics (TRAC-CAR-T lead, preclinical), Korecyte Bio (KOR101, preclinical; hypoxia-activated switch, pan-solid-tumor)","Disease Category":"Oncology / Autoimmune (unspecified)","Phase (most advanced)":"Preclinical to early clinical (IIT)","White Space Note":"Korecyte Bio (KOR101, preclinical) is the first identified in vivo CAR-T program targeting solid tumors — via a hypoxia-activated switch rather than a single named antigen (counted in the Undisclosed/platform-stage row above). Remaining white space: no in vivo program has disclosed a specific solid-tumor ANTIGEN target (e.g., mesothelin, HER2, CLDN18.2). Note: CREATE Medicines'' MT-304 targets HER2, but is a CAR-myeloid/multi-immune program, not CAR-T (see Pipeline Dashboard scope note) — it does not fill this white space. GPRC5D is excluded from this solid-tumor list; it is a plasma-cell antigen targeted for multiple myeloma (hematologic), not a solid-tumor antigen — see rows 10/BCMA x GPRC5D above.","Company Announcement URL":"https://www.fiercebiotech.com/biotech/kite-puts-16b-line-pair-chinas-pregene-another-vivo-car-t-deal","Credible Press Release URL":"https://endpoints.news/starna-therapeutics-raises-44m-to-advance-in-vivo-car-t-programs-after-early-clinical-data/"}', NULL);
