INSERT INTO change_log (version_id, module, record_key, change_type, previous_data_json, new_data_json, field_diffs_json) VALUES (1, 'catalyst_dashboard', '2026-05-31|Kelonia Therapeutics (KLN-1010)|Conference (ASCO)', 'new', NULL, '{"Date":"2026-05-31","Company / Asset":"Kelonia Therapeutics (KLN-1010)","Catalyst Type":"Conference (ASCO)","Catalyst":"Updated Phase 1 data: 100% ORR in 18 pts; MRD-neg in all evaluable; first pt >10 mo response","Impact":"Confirms durability and expanded cohort; validates platform pre-acquisition close","Source Note":"biospace.com / businesswire.com","Company Announcement URL":"https://keloniatx.com/kelonia-therapeutics-to-present-updated-clinical-data-at-2026-american-society-of-clinical-oncology-asco-annual-meeting-and-european-hematology-association-eha-2026-congress/","Press Release URL":"https://www.biospace.com/press-releases/kelonia-therapeutics-presents-updated-first-in-human-data-from-phase-1-inmmycar-study-of-kln-1010-in-vivo-bcma-car-t-therapy-at-the-2026-american-society-of-clinical-oncology-asco-annual-meeting"}', NULL);
INSERT INTO change_log (version_id, module, record_key, change_type, previous_data_json, new_data_json, field_diffs_json) VALUES (1, 'catalyst_dashboard', '2026-05-31|Starna Therapeutics (STR-P004)|Conference (ASCO)', 'new', NULL, '{"Date":"2026-05-31","Company / Asset":"Starna Therapeutics (STR-P004)","Catalyst Type":"Conference (ASCO)","Catalyst":"First clinical data disclosed for STR-P004 in autoimmune disease: escalating doses 0.03-0.1 mg/kg, up to 8 infusions (TITE-BOIN12 design), patients treated Sep 1, 2025 - Jan 20, 2026","Impact":"Names Starna''s previously unnamed lead asset and confirms the CD19 target; repeat-dosing design differentiates from single-infusion competitors","Source Note":"ASCO / JCO 2026 abstract e14519 (company-authored)","Company Announcement URL":"https://ascopubs.org/doi/pdfdirect/10.1200/JCO.2026.44.16_suppl.e14519","Press Release URL":"Undisclosed"}', NULL);
INSERT INTO change_log (version_id, module, record_key, change_type, previous_data_json, new_data_json, field_diffs_json) VALUES (1, 'catalyst_dashboard', '2026-06-14|Legend Biotech (LB2501)|Conference (EHA)', 'new', NULL, '{"Date":"2026-06-14","Company / Asset":"Legend Biotech (LB2501)","Catalyst Type":"Conference (EHA)","Catalyst":"EHA 2026 late-breaker: 100% ORR (6/6 DL2), 83.3% CR; no DLTs/SAEs/ICANS/deaths in 12 pts","Impact":"First clinical data for Legend Biotech''s in vivo CAR-T program; CD19/CD20 dual-targeting differentiator","Source Note":"Legend Biotech IR / GlobeNewswire","Company Announcement URL":"https://investors.legendbiotech.com/news-releases/news-release-details/legend-biotech-announces-late-breaking-oral-presentation-eha","Press Release URL":"https://www.globenewswire.com/news-release/2026/06/02/3305321/0/en/legend-biotech-announces-late-breaking-oral-presentation-at-eha-2026-showcasing-initial-phase-1-in-vivo-car-t-data-with-lb2501-in-non-hodgkin-lymphoma-nhl.html"}', NULL);
INSERT INTO change_log (version_id, module, record_key, change_type, previous_data_json, new_data_json, field_diffs_json) VALUES (1, 'catalyst_dashboard', '2026-07-16|Umoja Biopharma (UB-VV400)|Regulatory', 'new', NULL, '{"Date":"2026-07-16","Company / Asset":"Umoja Biopharma (UB-VV400)","Catalyst Type":"Regulatory","Catalyst":"FDA clears IND for UB-VV400, described by the company as the industry''s first known CD22-directed in vivo CAR-T; Phase 1/2 design includes patients who progressed after prior CAR-T","Impact":"Umoja''s second VivoVec program to reach US clinical trials; initial data from the China investigator-initiated trial guided to a major medical meeting in 2H 2026","Source Note":"umoja-biopharma.com (company release, Jul 16, 2026)","Company Announcement URL":"https://www.umoja-biopharma.com/news/umoja-biopharma-announces-fda-clearance-of-ind-application-for-ub-vv400-the-industrys-first-known-cd22-directed-in-vivo-car-t-cell-therapy-for-relapsed-refractory-b-cell-malignancies/","Press Release URL":"https://www.biopharminternational.com/view/umoja-biopharma-wins-fda-ind-clearance-for-first-cd22-directed-in-vivo-car-t-therapy"}', NULL);
