INSERT INTO change_log (version_id, module, record_key, change_type, previous_data_json, new_data_json, field_diffs_json) VALUES (1, 'funding_investment', 'Vivacta Bio|Series A + Series A+|Apr 29, 2026', 'new', NULL, '{"Company":"Vivacta Bio","Round":"Series A + Series A+","Date":"Apr 29, 2026","Amount":"$50M+","Lead / Notable Investors":"Series A led by Loyal Valley Capital; Series A+ led by Decheng Capital; with OrbiMed, Hankang Capital, Eisai Innovation Inc., C&D Emerging Industry Equity Investment; existing shareholders Qiming Venture Partners, Beijing Shunxi, Apricot Capital","Status":"Independent, clinical-stage (spin-off of Grit Biotherapeutics)","Note":"Funds GT801 (CD19 T-LNP/mRNA in vivo CAR-T) clinical trials and global operations","Company Announcement URL":"https://www.prnewswire.com/news-releases/vivacta-bio-closed-series-a-and-series-a-financing-of-over-us50-million-302756983.html","Credible Press Release URL":"https://allsci.com/news/funding/vivacta-biotechnology-closes-usd-50m-series-a-and-a-funding-for-car-t-therapies/"}', NULL);
INSERT INTO change_log (version_id, module, record_key, change_type, previous_data_json, new_data_json, field_diffs_json) VALUES (1, 'competitive_intelligence', 'Capstan Therapeutics', 'new', NULL, '{"Company":"Capstan Therapeutics","Parent (if acquired)":"AbbVie","Delivery Platform":"LNP-mRNA (anti-CD8 targeted)","Clinical Progress":"Phase 1 (CPTX2309)","Manufacturing Readiness":"Transient mRNA simplifies manufacturing vs. viral vectors","Strategic Camp":"AbbVie autoimmune-LNP axis","Key Differentiator":"Early, clean mover in LNP-mRNA autoimmune CAR-T","Company Announcement URL":"https://news.abbvie.com/2025-06-30-AbbVie-to-Acquire-Capstan-Therapeutics,-Further-Strengthening-Commitment-to-Transforming-Patient-Care-in-Immunology","Credible Press Release URL":"https://www.prnewswire.com/news-releases/abbvie-completes-acquisition-of-capstan-therapeutics-302533462.html"}', NULL);
INSERT INTO change_log (version_id, module, record_key, change_type, previous_data_json, new_data_json, field_diffs_json) VALUES (1, 'competitive_intelligence', 'Orna Therapeutics', 'new', NULL, '{"Company":"Orna Therapeutics","Parent (if acquired)":"Eli Lilly","Delivery Platform":"LNP + circular RNA","Clinical Progress":"Phase 1 (ORN-252)","Manufacturing Readiness":"LNP manufacturing infrastructure via Lilly","Strategic Camp":"Lilly two-modality camp (autoimmune arm)","Key Differentiator":"Circular RNA extends expression window vs. linear mRNA","Company Announcement URL":"https://investor.lilly.com/news-releases/news-release-details/lilly-acquire-orna-therapeutics-advance-cell-therapies","Credible Press Release URL":"https://www.prnewswire.com/news-releases/lilly-to-acquire-orna-therapeutics-to-advance-cell-therapies-302682157.html"}', NULL);
INSERT INTO change_log (version_id, module, record_key, change_type, previous_data_json, new_data_json, field_diffs_json) VALUES (1, 'competitive_intelligence', 'Kelonia Therapeutics', 'new', NULL, '{"Company":"Kelonia Therapeutics","Parent (if acquired)":"Eli Lilly","Delivery Platform":"Lentiviral (iGPS engineered particles)","Clinical Progress":"Phase 1 (KLN-1010); 100% ORR in 18 pts (ASCO 2026); FDA Fast Track granted","Manufacturing Readiness":"Company states it owns its manufacturing facility","Strategic Camp":"Lilly two-modality camp (oncology arm)","Key Differentiator":"100% ORR + MRD-neg in all evaluable pts (ASCO 2026, n=18); no lymphodepletion; first pt >10 mo MRD-neg response","Company Announcement URL":"https://investor.lilly.com/news-releases/news-release-details/lilly-acquire-kelonia-therapeutics-advance-vivo-car-t-cell","Credible Press Release URL":"https://www.prnewswire.com/news-releases/lilly-to-acquire-kelonia-therapeutics-to-advance-in-vivo-car-t-cell-therapies-302747122.html"}', NULL);
INSERT INTO change_log (version_id, module, record_key, change_type, previous_data_json, new_data_json, field_diffs_json) VALUES (1, 'competitive_intelligence', 'Interius BioTherapeutics', 'new', NULL, '{"Company":"Interius BioTherapeutics","Parent (if acquired)":"Gilead / Kite Pharma","Delivery Platform":"Lentiviral (CD7-targeted)","Clinical Progress":"Phase 1 (INT2104) — first-in-human dosing in Australia (Oct 2024); expanded to EU Jan 2025","Manufacturing Readiness":"Leverages Kite''s established cell-therapy manufacturing base","Strategic Camp":"Kite/Gilead lentiviral camp","Key Differentiator":"Clinical PK translation from ex vivo to in vivo cited as rationale for acquisition","Company Announcement URL":"https://www.gilead.com/news/news-details/2025/kite-to-acquire-interius-biotherapeutics-to-advance-in-vivo-platform","Credible Press Release URL":"https://www.statnews.com/2025/08/21/gilead-kite-pharma-acquires-interius-biotherapeutics/"}', NULL);
INSERT INTO change_log (version_id, module, record_key, change_type, previous_data_json, new_data_json, field_diffs_json) VALUES (1, 'competitive_intelligence', 'EsoBiotec', 'new', NULL, '{"Company":"EsoBiotec","Parent (if acquired)":"AstraZeneca","Delivery Platform":"Lentiviral (ENaBL nanobody)","Clinical Progress":"Phase 1 (ESO-T01) — most mature efficacy data disclosed to date","Manufacturing Readiness":"Undisclosed","Strategic Camp":"AstraZeneca lentiviral entry","Key Differentiator":"Early, peer-reviewed MM efficacy (Nature Medicine, 4/5 responses, 3 sCR); the one death was disease-related (spinal-cord compression from an extramedullary lesion), not treatment/ICANS","Company Announcement URL":"https://www.astrazeneca.com/media-centre/press-releases/2025/acquisition-of-esobiotec-completed.html","Credible Press Release URL":"https://www.biopharminternational.com/view/astrazeneca-acquire-esobiotec-boosting-cell-therapy-portfolio"}', NULL);
INSERT INTO change_log (version_id, module, record_key, change_type, previous_data_json, new_data_json, field_diffs_json) VALUES (1, 'competitive_intelligence', 'Orbital Therapeutics', 'new', NULL, '{"Company":"Orbital Therapeutics","Parent (if acquired)":"Bristol Myers Squibb","Delivery Platform":"LNP + circular RNA","Clinical Progress":"IND-enabling (OTX-201)","Manufacturing Readiness":"Undisclosed","Strategic Camp":"BMS autoimmune entry","Key Differentiator":"Positions BMS opposite Lilly/AbbVie in the autoimmune LNP race","Company Announcement URL":"https://www.biopharmadive.com/news/bristol-myers-acquire-orbital-in-vivo-cell-therapy/802573/","Credible Press Release URL":"https://www.cnbc.com/2025/10/10/bristol-myers-buys-orbital-therapeutics.html"}', NULL);
INSERT INTO change_log (version_id, module, record_key, change_type, previous_data_json, new_data_json, field_diffs_json) VALUES (1, 'competitive_intelligence', 'Umoja Biopharma', 'new', NULL, '{"Company":"Umoja Biopharma","Parent (if acquired)":"Independent","Delivery Platform":"Lentiviral (VivoVec) + RACR","Clinical Progress":"Phase 1 (UB-VV111); FDA Fast Track","Manufacturing Readiness":"Reported to have addressed lentiviral scale-up challenges","Strategic Camp":"Independent — most-cited remaining acquisition target","Key Differentiator":"RACR system removes need for chemo-based lymphodepletion","Company Announcement URL":"https://www.prnewswire.com/news-releases/abbvie-and-umoja-biopharma-announce-strategic-collaboration-to-develop-novel-in-situ-car-t-cell-therapies-302025722.html","Credible Press Release URL":"https://www.biospace.com/press-releases/umoja-biopharma-announces-that-ub-vv111-receives-fda-fast-track-designation-for-relapsed-refractory-b-cell-malignancies"}', NULL);
INSERT INTO change_log (version_id, module, record_key, change_type, previous_data_json, new_data_json, field_diffs_json) VALUES (1, 'competitive_intelligence', 'Sana Biotechnology', 'new', NULL, '{"Company":"Sana Biotechnology","Parent (if acquired)":"Independent (public)","Delivery Platform":"Fusogen-based (fusosome) delivery","Clinical Progress":"Discovery/Preclinical (in vivo CAR-T)","Manufacturing Readiness":"Public company; broader manufacturing base across programs","Strategic Camp":"Independent","Key Differentiator":"Hypoimmune fusogen approach differentiates from LNP/lentiviral peers","Company Announcement URL":"https://ir.sana.com/news-releases/news-release-details/sana-biotechnology-presents-preclinical-data-vivo-car-t-cell","Credible Press Release URL":"https://ir.sana.com/news-releases/news-release-details/sana-biotechnology-announces-oral-presentation-highlighting"}', NULL);
INSERT INTO change_log (version_id, module, record_key, change_type, previous_data_json, new_data_json, field_diffs_json) VALUES (1, 'competitive_intelligence', 'Starna Therapeutics / Pregene Biopharma / MagicRNA', 'new', NULL, '{"Company":"Starna Therapeutics / Pregene Biopharma / MagicRNA","Parent (if acquired)":"Independent (China-based)","Delivery Platform":"RNA/LNP or lentiviral (varies)","Clinical Progress":"Early Phase 1 (autoimmune/oncology)","Manufacturing Readiness":"Smaller scale; capital-efficient","Strategic Camp":"China-based independents","Key Differentiator":"Fast, lower-cost path to first-in-human data; global partnership potential (e.g., Pregene-Kite)","Company Announcement URL":"https://endpoints.news/starna-therapeutics-raises-44m-to-advance-in-vivo-car-t-programs-after-early-clinical-data/","Credible Press Release URL":"https://biopharmaapac.com/news/69/7099/starna-therapeutics-secures-over-rmb-300-million-in-series-b-financing-to-accelerate-in-vivo-car-t-innovation.html"}', NULL);
INSERT INTO change_log (version_id, module, record_key, change_type, previous_data_json, new_data_json, field_diffs_json) VALUES (1, 'competitive_intelligence', 'Legend Biotech', 'new', NULL, '{"Company":"Legend Biotech","Parent (if acquired)":"Independent (public)","Delivery Platform":"Lentiviral (TaVec)","Clinical Progress":"Phase 1 (LB2501); 100% ORR at DL2 (EHA 2026, n=12)","Manufacturing Readiness":"Public company; broader approved cell-therapy franchise","Strategic Camp":"Independent — largest standalone cell therapy company","Key Differentiator":"First-in-class CD19/CD20 dual-targeting in vivo CAR-T; no DLTs/SAEs/deaths; favorable safety vs. peers","Company Announcement URL":"https://investors.legendbiotech.com/news-releases/news-release-details/legend-biotech-announces-late-breaking-oral-presentation-eha","Credible Press Release URL":"https://www.globenewswire.com/news-release/2026/06/02/3305321/0/en/legend-biotech-announces-late-breaking-oral-presentation-at-eha-2026-showcasing-initial-phase-1-in-vivo-car-t-data-with-lb2501-in-non-hodgkin-lymphoma-nhl.html"}', NULL);
INSERT INTO change_log (version_id, module, record_key, change_type, previous_data_json, new_data_json, field_diffs_json) VALUES (1, 'competitive_intelligence', 'CREATE Medicines', 'new', NULL, '{"Company":"CREATE Medicines","Parent (if acquired)":"Independent","Delivery Platform":"mRNA-LNP (non-integrating)","Clinical Progress":"Phase 1/2 (CRT-402; HREC-approved, not yet dosed)","Manufacturing Readiness":"Company states it has dosed >50 patients across its broader in vivo CAR clinical programs — largest disclosed in vivo CAR dataset","Strategic Camp":"Independent — most clinically experienced in vivo CAR company (largely CAR-myeloid); CAR-T program CRT-402 not yet dosed","Key Differentiator":"Broadest in vivo CAR clinical dataset (>50 pts) — but mostly CAR-myeloid oncology (MT-302/MT-303/MT-304); its CAR-T candidate CRT-402 is HREC-approved, not yet dosed","Company Announcement URL":"https://www.prnewswire.com/news-releases/create-medicines-receives-approval-to-initiate-first-in-human-phase-12-clinical-trial-of-in-vivo-car-t-candidate-crt-402-for-autoimmune-diseases-302838482.html","Credible Press Release URL":"https://www.precisionmedicineonline.com/business-news/create-medicines-start-its-first-vivo-car-t-trial-autoimmune-diseases"}', NULL);
INSERT INTO change_log (version_id, module, record_key, change_type, previous_data_json, new_data_json, field_diffs_json) VALUES (1, 'competitive_intelligence', 'Vyriad', 'new', NULL, '{"Company":"Vyriad","Parent (if acquired)":"Independent","Delivery Platform":"Lentiviral (G-Link / direct covalent display retargeting)","Clinical Progress":"Preclinical (VV169; clinical entry expected later 2026)","Manufacturing Readiness":"Privately held; Series B-backed manufacturing scale-up underway","Strategic Camp":"Independent — remaining privately-held lentiviral platform company","Key Differentiator":"Modular, non-genetic lentiviral retargeting (G-Link) avoids re-engineering the vector for each new target","Company Announcement URL":"https://vyriad.com/newsevents/vyriad-unveils-lead-in-vivo-car-t-candidate-vv169-and-data-supporting-future-clinical-development-during-ash-2025/","Credible Press Release URL":"https://www.biospace.com/press-releases/vyriad-unveils-lead-in-vivo-car-t-candidate-vv169-and-data-supporting-future-clinical-development-during-ash-2025"}', NULL);
INSERT INTO change_log (version_id, module, record_key, change_type, previous_data_json, new_data_json, field_diffs_json) VALUES (1, 'competitive_intelligence', 'Genocury Biotech', 'new', NULL, '{"Company":"Genocury Biotech","Parent (if acquired)":"Independent","Delivery Platform":"Vivoexpress LNP/mRNA (non-integrating)","Clinical Progress":"Early Phase 1 (JY231; n=1 CR reported)","Manufacturing Readiness":"Undisclosed","Strategic Camp":"China-based independent","Key Differentiator":"Among the first disclosed human in vivo CAR-T efficacy signals (Apr 2025, n=1 IIT) — note: company press release, not peer-reviewed","Company Announcement URL":"https://www.prnewswire.com/news-releases/genocury-biotech-annouces-groundbreaking-advance-in-relapsedrefractory-dlbcl-through-pioneering-in-vivo-cd19-car-t-therapy-302442371.html","Credible Press Release URL":"https://www.curetoday.com/view/in-vivo-cd19-car-t-leads-to-remission-in-dlbcl-without-lymphodepletion"}', NULL);
INSERT INTO change_log (version_id, module, record_key, change_type, previous_data_json, new_data_json, field_diffs_json) VALUES (1, 'competitive_intelligence', 'Immorna', 'new', NULL, '{"Company":"Immorna","Parent (if acquired)":"Independent","Delivery Platform":"mRNA / self-replicating RNA + LNP","Clinical Progress":"Phase 1 (JCXH-213; n=1, systemic sclerosis)","Manufacturing Readiness":"Undisclosed","Strategic Camp":"China-based independent — autoimmune entrant","Key Differentiator":"First tissue (lymph node)-level B-cell depletion shown for an in vivo CAR-T, alongside Lilly''s Orna Therapeutics as one of two autoimmune dosing entrants","Company Announcement URL":"https://www.immornabio.com/News-details/41.html","Credible Press Release URL":"https://endpoints.news/in-vivo-car-t-race-for-autoimmune-grows-as-two-rna-startups-enter-the-clinic/"}', NULL);
INSERT INTO change_log (version_id, module, record_key, change_type, previous_data_json, new_data_json, field_diffs_json) VALUES (1, 'competitive_intelligence', 'Vivacta Bio', 'new', NULL, '{"Company":"Vivacta Bio","Parent (if acquired)":"Independent (spin-off of Grit Biotherapeutics)","Delivery Platform":"CLAMP T-LNP + mRNA in vivo CAR-T","Clinical Progress":"Phase 1 (GT801); investigator-initiated first-in-human, ASH 2025","Manufacturing Readiness":"Undisclosed","Strategic Camp":"China-based independent — clinical-stage entrant","Key Differentiator":"Spin-off leveraging Grit Biotherapeutics'' CLAMP site-specific antibody conjugation technology; $50M+ Series A/A+ (Apr 2026)","Company Announcement URL":"https://www.prnewswire.com/news-releases/vivacta-bio-closed-series-a-and-series-a-financing-of-over-us50-million-302756983.html","Credible Press Release URL":"https://www.prnewswire.com/news-releases/vivacta-bio-announces-promising-first-in-human-results-for-gt801-an-in-vivo-car-t-therapy-in-non-hodgkins-lymphoma-at-the-2025-ash-annual-meeting-302633966.html"}', NULL);
INSERT INTO change_log (version_id, module, record_key, change_type, previous_data_json, new_data_json, field_diffs_json) VALUES (1, 'competitive_intelligence', 'NanoCell Therapeutics', 'new', NULL, '{"Company":"NanoCell Therapeutics","Parent (if acquired)":"Independent","Delivery Platform":"tLNP non-viral DNA in vivo CAR-T (NCtx, transposase integration)","Clinical Progress":"Preclinical (CAR.CD22); IMPD filing initiated in Europe","Manufacturing Readiness":"Undisclosed","Strategic Camp":"Independent — preclinical, transatlantic (US/Netherlands)","Key Differentiator":"Only tracked program combining LNP delivery with durable (transposase-mediated) integration, avoiding viral vectors; partnered with OneChain Immunotherapeutics for the CD22 CAR","Company Announcement URL":"https://nanocelltx.com/technology/","Credible Press Release URL":"https://www.biopharminternational.com/view/nanocell-lnp-platform-shows-promise-in-vivo-car-t-development"}', NULL);
INSERT INTO change_log (version_id, module, record_key, change_type, previous_data_json, new_data_json, field_diffs_json) VALUES (1, 'competitive_intelligence', 'Azalea Therapeutics', 'new', NULL, '{"Company":"Azalea Therapeutics","Parent (if acquired)":"Independent","Delivery Platform":"TRAC-locus in vivo CAR-T (EDV + AAV, CRISPR-Cas9)","Clinical Progress":"Preclinical; first-in-primate data (May 2026), no clinical asset named yet","Manufacturing Readiness":"Undisclosed","Strategic Camp":"Independent — preclinical, backed by Third Rock Ventures","Key Differentiator":"Only tracked program using CRISPR-Cas9 site-specific genomic integration (TRAC locus) rather than random integration or transient RNA; $82M launch financing (Nov 2025)","Company Announcement URL":"https://azaleatx.com/","Credible Press Release URL":"https://www.globenewswire.com/news-release/2025/11/04/3180290/0/en/Azalea-Therapeutics-Launches-with-82-Million-Financing-to-Redefine-Precision-Genomic-Medicines-by-Engineering-Cells-Directly-Inside-Each-Patient.html"}', NULL);
INSERT INTO change_log (version_id, module, record_key, change_type, previous_data_json, new_data_json, field_diffs_json) VALUES (1, 'competitive_intelligence', 'Korecyte Bio', 'new', NULL, '{"Company":"Korecyte Bio","Parent (if acquired)":"Independent","Delivery Platform":"HypoxiCAR (hypoxia-activated in vivo lentiviral transduction)","Clinical Progress":"Preclinical (KOR101); finalizing preclinical package, first CTA in preparation","Manufacturing Readiness":"Undisclosed","Strategic Camp":"Independent — preclinical, UK/Netherlands, King''s College London spinout","Key Differentiator":"Only solid-tumor-targeted in vivo CAR-T in this tracker; hypoxia-sensing switch keeps CAR-T dormant until it enters the low-oxygen tumor microenvironment","Company Announcement URL":"https://korecyte.com/technology/","Credible Press Release URL":"https://www.bioprocessintl.com/deal-making/cgt-catapult-teams-with-korecyte-bio-on-low-oxygen-car-t-platform"}', NULL);
